<?php
namespace Tests\Unit;
use App\Services\B2BMatching;
use PHPUnit\Framework\TestCase;
class B2BEvidenceTest extends TestCase
{
 private function complete(): array {return ['categories'=>[1],'products'=>[['name_en'=>'Organic herbs','name_ar'=>'أعشاب عضوية']],'catalogue_evidence'=>'Reviewed catalogue','required_products'=>['herbs'],'preferred_origins'=>['Egypt'],'origin'=>'Egypt','origin_evidence'=>'Reviewed origin','quantity'=>10,'capacity'=>100,'unit'=>'kg','capacity_verified'=>true,'capacity_evidence'=>'Reviewed supply','required_certifications'=>['Organic'],'certifications'=>[['name'=>'Organic','verified'=>true,'evidence'=>'Reviewed certificate']],'meeting_interests'=>['wholesale']];}
 public function test_category_only_is_not_a_strong_match(): void {$r=(new B2BMatching)->compare(['categories'=>[1]],['categories'=>[1]]);$this->assertSame(35,$r['score']);$this->assertSame(35,$r['evidence_coverage']);$this->assertSame('requires_human_review',$r['recommendation']);}
 public function test_complete_evidence_supports_a_strong_unapproved_recommendation(): void {$p=$this->complete();$r=(new B2BMatching)->compare($p,$p);$this->assertSame(100,$r['score']);$this->assertSame(100,$r['evidence_coverage']);$this->assertSame('strong_match',$r['recommendation']);$this->assertArrayNotHasKey('meeting_id',$r);}
 public function test_required_unverified_certification_blocks_clearance(): void {$e=$this->complete();$e['certifications']=[];$r=(new B2BMatching)->compare($this->complete(),$e);$this->assertSame('unknown',$r['factors']['documentation']['state']);$this->assertNotEmpty($r['blockers']);$this->assertSame('potential_match_needs_information',$r['recommendation']);}
 public function test_verified_insufficient_capacity_is_incompatible(): void {$e=$this->complete();$e['capacity']=1;$r=(new B2BMatching)->compare($this->complete(),$e);$this->assertSame('verified_mismatch',$r['factors']['capacity']['state']);$this->assertSame('incompatible',$r['recommendation']);}
 public function test_explicit_no_restriction_is_distinct_from_unknown(): void {$p=$this->complete();$p['preferred_origins']=[];$p['required_certifications']=[];$a=(new B2BMatching)->compare($p,$this->complete());$p['requirement_states']=['origin'=>'not_applicable','documentation'=>'not_applicable'];$b=(new B2BMatching)->compare($p,$this->complete());$this->assertSame('unknown',$a['factors']['origin']['state']);$this->assertSame('not_applicable',$b['factors']['origin']['state']);$this->assertSame(0,$b['factors']['origin']['points']);$this->assertGreaterThan($a['evidence_coverage'],$b['evidence_coverage']);$this->assertSame([],$b['blockers']);}
 public function test_missing_catalogue_is_unknown_not_proven_unavailable(): void {$e=$this->complete();unset($e['catalogue_evidence']);$r=(new B2BMatching)->compare($this->complete(),$e);$this->assertSame('unknown',$r['factors']['products']['state']);$this->assertSame('requires_human_review',$r['recommendation']);}
 public function test_arabic_is_unicode_substring_matching(): void {$p=$this->complete();$p['required_products']=['أعشاب'];$r=(new B2BMatching)->compare($p,$this->complete());$this->assertSame('verified_match',$r['factors']['products']['state']);$p['required_products']=['غير موجود'];$r=(new B2BMatching)->compare($p,$this->complete());$this->assertSame('verified_mismatch',$r['factors']['products']['state']);}
 public function test_explicit_unknown_never_rewards_leftover_values(): void {$p=$this->complete();$p['requirement_states']=['origin'=>'unknown'];$r=(new B2BMatching)->compare($p,$this->complete());$this->assertSame('unknown',$r['factors']['origin']['state']);$this->assertSame(0,$r['factors']['origin']['points']);$this->assertNotSame('strong_match',$r['recommendation']);}
}
